; Bounded strip transaction: no foreground callbacks between restore and redraw.
; Shadow is enabled only for strip duration and restored exactly before return.
; Dirty glyph cells are regenerated by sw_prepare; no saved drone background.
                    longa  on
                    longi  on
sw_draw_strip       lda    rw_strip
                    cmp    #25
                    bcc    sw_strip_valid
                    lda    #1
                    rts
sw_strip_valid      asl    a
                    asl    a
                    asl    a
                    sta    sw_strip_top
                    clc
                    adc    #8
                    sta    sw_strip_stop
                    sep    #$20
                    longa  off
                    lda    >$e0c035
                    sta    sw_shadow
                    and    #$f7
                    sta    >$e0c035
                    rep    #$20
                    longa  on
; Black erasure then current glyph regeneration, all before sprite redraw.
                    lda    rw_strip
                    asl    a
                    tax
                    lda    sw_cell_start,x
                    sta    sw_cell_begin
                    lda    sw_cell_start+2,x
                    sta    sw_cell_limit
                    lda    sw_cell_begin
                    sta    sw_cell_cursor
sw_draw_cell        lda    sw_cell_cursor
                    cmp    sw_cell_limit
                    bcs    sw_passes_complete
                    tax
                    lda    sw_cell_jobs,x
                    sta    sw_cell_flags
                    and    #$fffc
                    tax
                    lda    sw_cell_flags
                    and    #2
                    bne    sw_copy_cell_call
; A glyph restore overwrites the entire cell, so never black it first.
; All background work precedes all sprites in this disjoint eight-row region.
                    lda    sw_strip_top
                    beq    sw_draw_cell_skip
                    jsr    sw_zero_cell
                    bra    sw_draw_cell_skip
sw_copy_cell_call   jsr    sw_copy_cell
sw_draw_cell_skip   inc    sw_cell_cursor
                    inc    sw_cell_cursor
                    bra    sw_draw_cell
sw_passes_complete  anop
                    lda    rw_strip
                    asl    a
                    tax
                    lda    sw_job_start,x
                    sta    sw_job_cursor
                    lda    sw_job_start+2,x
                    sta    sw_job_limit
sw_job_loop         lda    sw_job_cursor
                    cmp    sw_job_limit
                    bcs    sw_job_done
                    tax
                    lda    sw_jobs,x
                    tax
                    ldy    #0
sw_load_cache       lda    sw_objects,x
                    sta    ro_x,y
                    inx
                    inx
                    iny
                    iny
                    cpy    #10
                    bcc    sw_load_cache
                    ldx    sw_job_cursor
                    lda    sw_job_firsts,x
                    sta    ns_first
                    lda    sw_job_stops,x
                    sta    ns_stop
                    jsr    ns_draw
                    cmp    #0
                    bne    sw_strip_fault
                    inc    sw_job_cursor
                    inc    sw_job_cursor
                    bra    sw_job_loop
sw_job_done         anop
                    lda    #0
                    bra    sw_strip_restore
sw_strip_fault      lda    #1
sw_strip_restore    pha
                    sep    #$20
                    longa  off
                    lda    sw_shadow
                    sta    >$e0c035
                    rep    #$20
                    longa  on
                    pla
                    rts
sw_strip_top        ds     2
sw_strip_stop       ds     2
sw_pass             ds     2
sw_rows             ds     2
sw_dst              ds     2
sw_rank             ds     2
sw_shadow           ds     2
sw_job_cursor       ds     2
sw_job_limit        ds     2

sw_cell_begin       ds     2
sw_cell_limit       ds     2
sw_cell_cursor      ds     2

sw_cell_flags       ds     2

; Fixed eight-row cells: normal stack, IRQs enabled.
; X is the aligned cell base; every long access remains inside its strip.
sw_zero_cell        lda    #0
                    sta    >$012000,x
                    sta    >$012002,x
                    sta    >$0120a0,x
                    sta    >$0120a2,x
                    sta    >$012140,x
                    sta    >$012142,x
                    sta    >$0121e0,x
                    sta    >$0121e2,x
                    sta    >$012280,x
                    sta    >$012282,x
