                    sta    >$012322,x
                    sta    >$0123c0,x
                    sta    >$0123c2,x
                    sta    >$012460,x
                    sta    >$012462,x
                    rts
sw_copy_cell        anop
sw_copy_glyph       lda    >rr_background,x
                    sta    >$012000,x
                    lda    >rr_background+2,x
                    sta    >$012002,x
                    lda    >rr_background+160,x
                    sta    >$0120a0,x
                    lda    >rr_background+162,x
                    sta    >$0120a2,x
                    lda    >rr_background+320,x
                    sta    >$012140,x
                    lda    >rr_background+322,x
                    sta    >$012142,x
                    lda    >rr_background+480,x
                    sta    >$0121e0,x
                    lda    >rr_background+482,x
                    sta    >$0121e2,x
                    lda    >rr_background+640,x
                    sta    >$012280,x
                    lda    >rr_background+642,x
                    sta    >$012282,x
                    lda    >rr_background+800,x
                    sta    >$012320,x
                    lda    >rr_background+802,x
